e,"expression":"iif({cod_padre_nonso} = true, ''?'', {cod_padre})"},{"name":"forma_test","expression":"iif({cod_cifra} anyof [''0'', ''2'', ''4'', ''6'', ''8''], ''A'', ''B'')","includeIntoResult":true},{"name":"ctx03_k","includeIntoResult":true,"expression":"iif({ctx03} anyof [3, 4, 5], 3, {ctx03})"}],"pages":[{"name":"p001_qd01","elements":[{"type":"html","name":"qd01","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Questa ricerca vuole capire che cosa pensa chi ha la tua età dei giochi in cui si puntano soldi (scommesse, gratta e vinci) e degli acquisti a sorpresa nei videogiochi.</p><p style=\"margin:0 0 6px;line-height:1.6;\">Puoi rispondere anche se non giochi.</p><p style=\"margin:0 0 6px;line-height:1.6;\"><strong style=\"color:#286181\">Non è una verifica: niente voti.</strong></p></div><div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\"><strong style=\"color:#286181\">Non scrivere il tuo nome: le risposte sono riservate.</strong></p><p style=\"margin:0 0 6px;line-height:1.6;\">Le leggono solo i ricercatori e il responsabile del progetto, mai insegnanti o genitori.</p></div><div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\"><strong style=\"color:#286181\">Partecipare è libero: puoi saltare qualsiasi domanda o smettere quando vuoi, senza conseguenze.</strong></p></div><div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Alcune domande hanno una risposta giusta.</p><p style=\"margin:0 0 6px;line-height:1.6;\">Se non la sai, scegli «Non lo so»: va bene.</p></div><div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Ci vogliono circa 30 minuti.</p></div><div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Il questionario registra anche quanto tempo resti su ogni pagina e il tipo di schermo che usi: ci serve solo a capire se le domande sono troppo lunghe o difficili.</p></div>"},{"name":"consent_assenso","title":"Ho letto queste informazioni e voglio partecipare.","type":"boolean","renderAs":"checkbox","isRequired":true,"label":"Ho letto queste informazioni e voglio partecipare.","titleLocation":"hidden","requiredErrorText":"Questa risposta serve per andare avanti."},{"name":"impegno_iniziale","title":"Ti chiediamo di leggere ogni domanda e di rispondere con attenzione. Te la senti?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Sì, mi impegno"},{"value":2,"text":"No"}]}],"title":"Benvenuto, benvenuta"},{"name":"p002_cod_madre","elements":[{"type":"html","name":"stim_cod_madre","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Ora crea il tuo codice segreto: serve a collegare i tuoi questionari dei prossimi mesi senza che nessuno sappia chi sei.</p></div>"},{"type":"panel","name":"nxcard_cod_madre","title":"Prima lettera del nome di tua madre (es. Laura → L)","description":"Scrivi una sola lettera.","elements":[{"name":"cod_madre","title":"Prima lettera del nome di tua madre (es. Laura → L)","type":"text","inputType":"text","maxLength":1,"autocomplete":"off","description":"","placeholder":"","validators":[{"type":"regex","regex":"^[A-Za-zÀ-ÖØ-öø-ÿ]$","text":"Scrivi una sola lettera."}],"isRequired":true,"requiredErrorText":"Questa risposta serve per andare avanti.","titleLocation":"hidden","visibleIf":"{cod_madre_nonso} <> true"},{"type":"boolean","name":"cod_madre_nonso","renderAs":"checkbox","titleLocation":"hidden","title":"Non la conosco","label":"Non la conosco"}]},{"type":"panel","name":"nxcard_cod_padre","title":"Prima lettera del nome di tuo padre (es. Omar → O)","description":"Scrivi una sola lettera.","elements":[{"name":"cod_padre","title":"Prima lettera del nome di tuo padre (es. Omar → O)","type":"text","inputType":"text","maxLength":1,"autocomplete":"off","description":"","placeholder":"","validators":[{"type":"regex","regex":"^[A-Za-zÀ-ÖØ-öø-ÿ]$","text":"Scrivi una sola lettera."}],"isRequired":true,"requiredErrorText":"Questa risposta serve per andare avanti.","titleLocation":"hidden","visibleIf":"{cod_padre_nonso} <> true"},{"type":"boolean","name":"cod_padre_nonso","renderAs":"checkbox","titleLocation":"hidden","title":"Non la conosco","label":"Non la conosco"}]},{"name":"cod_mese","title":"Il tuo mese di nascita","type":"dropdown","placeholder":"Scegli...","choices":[{"value":"01","text":"Gennaio"},{"value":"02","text":"Febbraio"},{"value":"03","text":"Marzo"},{"value":"04","text":"Aprile"},{"value":"05","text":"Maggio"},{"value":"06","text":"Giugno"},{"value":"07","text":"Luglio"},{"value":"08","text":"Agosto"},{"value":"09","text":"Settembre"},{"value":"10","text":"Ottobre"},{"value":"11","text":"Novembre"},{"value":"12","text":"Dicembre"}],"isRequired":true,"requiredErrorText":"Questa risposta serve per andare avanti."},{"name":"cod_cifra","title":"Ultima cifra del giorno del tuo compleanno (es. 17 marzo → 7; 5 marzo → 5; 30 marzo → 0)","type":"dropdown","placeholder":"Scegli...","choices":[{"value":"0","text":"0"},{"value":"1","text":"1"},{"value":"2","text":"2"},{"value":"3","text":"3"},{"value":"4","text":"4"},{"value":"5","text":"5"},{"value":"6","text":"6"},{"value":"7","text":"7"},{"value":"8","text":"8"},{"value":"9","text":"9"}],"isRequired":true,"requiredErrorText":"Questa risposta serve per andare avanti."},{"name":"cod_cognome","title":"Ultima lettera del tuo cognome, come lo scrivi a scuola (es. Rossi → I)","type":"text","inputType":"text","maxLength":1,"autocomplete":"off","description":"Scrivi una sola lettera.","placeholder":"","validators":[{"type":"regex","regex":"^[A-Za-zÀ-ÖØ-öø-ÿ]$","text":"Scrivi una sola lettera."}],"isRequired":true,"requiredErrorText":"Questa risposta serve per andare avanti."},{"name":"ctx03","title":"Genere: come ti descrivi?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Ragazza"},{"value":2,"text":"Ragazzo"},{"value":3,"text":"Non binario"},{"value":4,"text":"In un altro modo"},{"value":5,"text":"Preferisco non rispondere"}]}],"title":"Il tuo codice","nx_section_title":"Il tuo codice","nx_section_id":"codice","description":"Circa 1 minuto"},{"name":"p003_cur01","elements":[{"type":"html","name":"stim_cur01","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Qui «scommettere» vuol dire <strong style=\"color:#286181\">puntare soldi veri sperando di vincerne di più</strong>: scommesse sulle partite, gratta e vinci, slot, poker o casinò online.</p><p style=\"margin:0 0 6px;line-height:1.6;\">A qualcuno le scommesse interessano, ad altri no: rispondi pensando a te, in questo periodo.</p></div>"},{"name":"cur01","title":"Per me, scommettere soldi veri è una cosa...","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Molto brutta"},{"value":2,"text":"Abbastanza brutta"},{"value":3,"text":"Né brutta né bella"},{"value":4,"text":"Abbastanza bella"},{"value":5,"text":"Molto bella"}]}],"nx_block":"opinioni","title":"Che cosa ne pensi","nx_section_title":"Che cosa ne pensi","nx_section_id":"opinioni","description":"Circa 2 minuti"},{"name":"p004_cur02","elements":[{"name":"cur02","title":"Per me, scommettere soldi veri è una cosa...","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Molto sgradevole"},{"value":2,"text":"Abbastanza sgradevole"},{"value":3,"text":"Né sgradevole né piacevole"},{"value":4,"text":"Abbastanza piacevole"},{"value":5,"text":"Molto piacevole"}]}],"nx_block":"opinioni"},{"name":"p005_cur03","elements":[{"name":"cur03","title":"Quanta curiosità ti fa l''idea di fare tu una scommessa con soldi veri?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Nessuna"},{"value":2,"text":"Poca"},{"value":3,"text":"Abbastanza"},{"value":4,"text":"Molta"},{"value":5,"text":"Moltissima"}]}],"nx_block":"opinioni"},{"name":"p006_cur04","elements":[{"name":"cur04","title":"Quanta voglia hai di fare una scommessa con soldi veri?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Nessuna"},{"value":2,"text":"Poca"},{"value":3,"text":"Abbastanza"},{"value":4,"text":"Molta"},{"value":5,"text":"Moltissima"}]}],"nx_block":"opinioni"},{"name":"p007_int01","elements":[{"type":"html","name":"desc_int01","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;color:#4a5560;font-size:0.95em\">Pensa ai prossimi 3 mesi, cioè fino a [mese].</p><p style=\"margin:0 0 6px;line-height:1.6;color:#4a5560;font-size:0.95em\">C&#x27;è chi fa queste cose e chi no: rispondi pensando a cosa farai davvero.</p><p style=\"margin:0 0 6px;line-height:1.6;color:#4a5560;font-size:0.95em\"><strong style=\"color:#286181\">Pensi che lo farai?</strong></p></div>"},{"name":"int01","title":"Giocare soldi veri per provare a vincerne altri (gratta e vinci, lotto, scommesse, slot machine, carte o poker con soldi), anche online.","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Sicuramente no"},{"value":2,"text":"Probabilmente no"},{"value":3,"text":"Probabilmente sì"},{"value":4,"text":"Sicuramente sì"}]}],"nx_block":"opinioni"},{"name":"p008_int02","elements":[{"type":"html","name":"desc_int02","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;color:#4a5560;font-size:0.95em\">Pensa ai prossimi 3 mesi, cioè fino a [mese].</p><p style=\"margin:0 0 6px;line-height:1.6;color:#4a5560;font-size:0.95em\">C&#x27;è chi fa queste cose e chi no: rispondi pensando a cosa farai davvero.</p><p style=\"margin:0 0 6px;line-height:1.6;color:#4a5560;font-size:0.95em\"><strong style=\"color:#286181\">Pensi che lo farai?</strong></p></div>"},{"name":"int02","title":"Scommettere soldi su partite o gare sportive (per esempio una schedina sul calcio), per conto tuo o con altre persone, anche online.","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Sicuramente no"},{"value":2,"text":"Probabilmente no"},{"value":3,"text":"Probabilmente sì"},{"value":4,"text":"Sicuramente sì"}]}],"nx_block":"opinioni"},{"name":"p009_istr_test","elements":[{"type":"html","name":"istr_test","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Ora leggerai alcune situazioni.</p><p style=\"margin:0 0 6px;line-height:1.6;\">In molte domande c&#x27;è una sola risposta giusta: scegli quella che ti sembra migliore.</p><p style=\"margin:0 0 6px;line-height:1.6;\"><strong style=\"color:#286181\">Se non la sai, scegli «Non lo so».</strong></p></div>"}],"nx_block":"test","title":"Situazioni e scelte","nx_section_title":"Situazioni e scelte","nx_section_id":"test","description":"Circa 7 minuti","nx_block_fixed":true},{"name":"p010_tlt01a","elements":[{"type":"html","name":"stim_tlt01a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">A ogni estrazione del lotto escono 5 numeri su 90: ogni numero ha 1 probabilità su 18 di uscire. Il 47 non esce da 100 estrazioni di fila.</p></div>","visibleIf":"({forma_test} = ''A'')"},{"name":"tlt01a","title":"Quanto è probabile che esca alla prossima estrazione?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Più del solito: dopo 100 estrazioni tocca a lui"},{"value":2,"text":"Quasi certo: in media esce una volta ogni 18"},{"value":3,"text":"Meno del solito: il lotto evita i numeri più giocati"},{"value":4,"text":"Come sempre, 1 su 18: il passato non conta"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"test"},{"name":"p011_tlt02a","elements":[{"type":"html","name":"stim_tlt02a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Gioco online: 25 caselle, 3 bombe nascoste. Ogni casella senza bomba fa salire la vincita. Puoi incassare quando vuoi; se trovi una bomba, perdi la puntata. In media il sito restituisce 97 centesimi per euro puntato.</p></div>","visibleIf":"({forma_test} = ''A'')"},{"name":"tlt02a","title":"Scegliendo quando fermarsi, che cosa può cambiare chi gioca?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Quanto spesso vince, non quanto perde in media"},{"value":2,"text":"Quanto perde in media: chi si ferma presto perde meno"},{"value":3,"text":"Molto: con la pratica si sente il momento giusto"},{"value":4,"text":"Niente: in questo gioco si perde sempre"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"test"},{"name":"p012_tlt03a","elements":[{"type":"html","name":"stim_tlt03a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">In un gratta e vinci si vincono 100.000 euro trovando tre corone. Su molti biglietti perdenti compaiono due corone e un altro simbolo. Elena ne ha appena grattato uno.</p></div>","visibleIf":"({forma_test} = ''A'')"},{"name":"tlt03a","title":"Che cosa è vero su questi biglietti?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Sono perdite che sembrano quasi vincite"},{"value":2,"text":"Annunciano che la vincita grande è vicina"},{"value":3,"text":"Indicano che bisogna scegliere meglio il biglietto"},{"value":4,"text":"Servono a pagare meno vincite ' WHERE id = '634d0f93-ca2e-56a3-ab6e-ded17f13de95';
UPDATE _ludolab_schema_tmp SET s = s || 'vere"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"test"},{"name":"p013_tlt04a","elements":[{"type":"html","name":"stim_tlt04a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Kevin scommette online sul calcio virtuale: partite simulate al computer ogni tre minuti. Perde 30 euro e pensa: &#x27;Se smetto ora, li ho persi per sempre. Continuo finché torno in pari.&#x27;</p></div>","visibleIf":"({forma_test} = ''A'')"},{"name":"tlt04a","title":"Che cosa è vero sul piano di Kevin?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Ha senso: smettere vuol dire accettare la perdita"},{"value":2,"text":"Funziona, se a ogni perdita raddoppia la puntata"},{"value":3,"text":"Sbaglia solo il momento: meglio recuperare domani, con calma"},{"value":4,"text":"Anche le puntate per recuperare fanno perdere, in media"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"test"},{"name":"p014_tlt05a","elements":[{"type":"html","name":"stim_tlt05a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Un sito accetta scommesse su una partita di videogiochi tra due squadre. Chi indovina riceve 1,85 euro per ogni euro puntato. In tutto si puntano 1.000 euro: 500 su ciascuna squadra.</p></div>","visibleIf":"({forma_test} = ''A'')"},{"name":"tlt05a","title":"Che cosa succede al sito dopo la partita?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Va in pari: metà vince e metà perde"},{"value":2,"text":"Guadagna o perde, secondo la squadra che vince"},{"value":3,"text":"Guadagna 75 euro, qualunque squadra vinca"},{"value":4,"text":"Guadagna 500 euro: tiene le puntate perdenti"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"test"},{"name":"p015_tlt06a","elements":[{"type":"html","name":"stim_tlt06a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Su Instagram un casinò in criptovaluta promette: &#x27;Deposita 50 euro e te ne regaliamo altri 50!&#x27;. In piccolo: per ritirare il regalo devi prima puntare in tutto 2.000 euro.</p></div>","visibleIf":"({forma_test} = ''A'')"},{"name":"tlt06a","title":"Per il casinò, a cosa serve questa offerta?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"A farti giocare senza rischiare i tuoi soldi"},{"value":2,"text":"A farti puntare molto prima di poter ritirare"},{"value":3,"text":"A far credere a un regalo che non esiste"},{"value":4,"text":"A mettere un tetto a quanto puoi puntare in tutto"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"test"},{"name":"p016_tlt07a","elements":[{"type":"html","name":"stim_tlt07a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Un gioco per cellulare regala forzieri a chi entra nell&#x27;app. Si provano due versioni. Versione 1: un forziere ogni 7 accessi. Versione 2: il forziere arriva a caso, in media ogni 7 accessi.</p></div>","visibleIf":"({forma_test} = ''A'')"},{"name":"tlt07a","title":"Con quale versione i giocatori entrano più spesso?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Con la 2: non sapere quando arriva fa riprovare"},{"value":2,"text":"Con la 1: sapere quando arriva il premio motiva"},{"value":3,"text":"Uguale: in media i premi sono gli stessi"},{"value":4,"text":"Con la 1: i premi regolari creano più dipendenza"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"test"},{"name":"p017_tlt08a","elements":[{"type":"html","name":"stim_tlt08a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Sofia gioca a un videogioco di calcio sul cellulare. Perde cinque partite di fila e sta per chiudere l&#x27;app. Compare: &#x27;Solo per te! Pacchetto campioni a 1,99 euro invece di 9,99. Scade tra 15 minuti.&#x27;</p></div>","visibleIf":"({forma_test} = ''A'')"},{"name":"tlt08a","title":"Perché l''offerta arriva proprio adesso? Scegli il motivo più probabile.","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"È un caso: le offerte arrivano a tutti"},{"value":2,"text":"Il gioco vede che vuole smettere e la trattiene"},{"value":3,"text":"Il gioco vuole vendere i suoi dati ad altre aziende"},{"value":4,"text":"Il gioco vuole aiutarla dopo tante sconfitte"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"test"},{"name":"p018_tlt09a","elements":[{"type":"html","name":"stim_tlt09a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Uno streamer apre casse di skin in diretta su un sito a pagamento. Sullo schermo scorrono i nomi di chi, sul sito, ha appena trovato una skin rara.</p></div>","visibleIf":"({forma_test} = ''A'')"},{"name":"tlt09a","title":"Su chi guarda, che effetto ha più spesso quella lista?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Nessuno: chi guarda non si lascia influenzare"},{"value":2,"text":"Allontana: si capisce che il sito è una truffa"},{"value":3,"text":"Fa sembrare facile vincere e spinge a provare"},{"value":4,"text":"Informa: mostra quanto spesso si vince"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"test"},{"name":"p019_tlt10a","elements":[{"type":"html","name":"stim_tlt10a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Un gioco per cellulare vende casse a sorpresa da 2 euro. Un&#x27;associazione di genitori chiede di aggiungere una sola regola per proteggere chi le compra.</p></div>","visibleIf":"({forma_test} = ''A'')"},{"name":"tlt10a","title":"Quale di queste regole protegge di più?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Un avviso: ''Le casse possono creare dipendenza''"},{"value":2,"text":"Una cassa gratis dopo cinque senza premi rari"},{"value":3,"text":"Un tetto di spesa deciso prima e non alzabile"},{"value":4,"text":"Una lista dei premi rari trovati, per trasparenza"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"test"},{"name":"p020_tlt01b","elements":[{"type":"html","name":"stim_tlt01b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">In un videogioco ogni cassa a sorpresa ha 1 probabilità su 50 di contenere un coltello raro. Luca ne ha aperte 120, senza mai trovarlo.</p></div>","visibleIf":"({forma_test} = ''B'')"},{"name":"tlt01b","title":"Quanto è probabile che esca alla prossima cassa?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Come sempre, 1 su 50: il passato non conta"},{"value":2,"text":"Più del solito: dopo 120 casse tocca a lui"},{"value":3,"text":"Meno del solito: il gioco penalizza chi ne apre tante"},{"value":4,"text":"Quasi certo: in media esce una volta ogni 50"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"test"},{"name":"p021_tlt02b","elements":[{"type":"html","name":"stim_tlt02b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Gioco online: un razzo decolla e la vincita si moltiplica, per 1,5, per 2, per 5... Puoi incassare quando vuoi; se il razzo esplode prima, perdi la puntata. In media il sito restituisce 96 centesimi per euro puntato.</p></div>","visibleIf":"({forma_test} = ''B'')"},{"name":"tlt02b","title":"Scegliendo quando incassare, che cosa può cambiare chi gioca?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Molto: con la pratica si sente il momento giusto"},{"value":2,"text":"Quanto spesso vince, non quanto perde in media"},{"value":3,"text":"Niente: in questo gioco si perde sempre"},{"value":4,"text":"Quanto perde in media: chi incassa presto perde meno"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"test"},{"name":"p022_tlt03b","elements":[{"type":"html","name":"stim_tlt03b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">In un gioco per cellulare ogni giro di ruota costa 50 gemme. Spesso la ruota rallenta e si ferma subito dopo lo spicchio del premio più grande. Ad Amira è appena successo.</p></div>","visibleIf":"({forma_test} = ''B'')"},{"name":"tlt03b","title":"Che cosa è vero su questi giri?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Servono a dare meno premi grandi"},{"value":2,"text":"Sono perdite che sembrano quasi vincite"},{"value":3,"text":"Annunciano che il premio grande è vicino"},{"value":4,"text":"Indicano che bisogna scegliere meglio quando girare"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"test"},{"name":"p023_tlt04b","elements":[{"type":"html","name":"stim_tlt04b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Giada compra gratta e vinci online da 5 euro, uno dopo l&#x27;altro. Perde 25 euro e pensa: &#x27;Se smetto ora, li ho persi per sempre. Continuo finché torno in pari.&#x27;</p></div>","visibleIf":"({forma_test} = ''B'')"},{"name":"tlt04b","title":"Che cosa è vero sul piano di Giada?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Sbaglia solo il momento: meglio recuperare domani, con calma"},{"value":2,"text":"Anche i biglietti per recuperare fanno perdere, in media"},{"value":3,"text":"Ha senso: smettere vuol dire accettare la perdita"},{"value":4,"text":"Funziona, se a ogni perdita compra biglietti più cari"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"test"},{"name":"p024_tlt05b","elements":[{"type":"html","name":"stim_tlt05b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Un casinò online lancia una moneta virtuale: si scommette su testa o croce. Chi indovina riceve 1,90 euro per ogni euro puntato. In tutto si puntano 800 euro: 400 su testa e 400 su croce.</p></div>","visibleIf":"({forma_test} = ''B'')"},{"name":"tlt05b","title":"Che cosa succede al casinò dopo il lancio?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Va in pari: metà vince e metà perde"},{"value":2,"text":"Guadagna 400 euro: tiene le puntate perdenti"},{"value":3,"text":"Guadagna 40 euro, qualunque lato esca"},{"value":4,"text":"Guadagna o perde, secondo il lato che esce"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"test"},{"name":"p025_tlt06b","elements":[{"type":"html","name":"stim_tlt06b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Un&#x27;app di casinò online promette: &#x27;Prima ora senza rischi: se perdi, ti rimborsiamo fino a 30 euro!&#x27;. In piccolo: il rimborso è un bonus da puntare 10 volte prima di ritirarlo.</p></div>","visibleIf":"({forma_test} = ''B'')"},{"name":"tlt06b","title":"Per l''app, a cosa serve questa offerta?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"A mettere un tetto a quanto puoi perdere in un''ora"},{"value":2,"text":"A far credere a un rimborso che non esiste"},{"value":3,"text":"A farti giocare senza rischiare i tuoi soldi"},{"value":4,"text":"A farti puntare ancora dopo che hai perso"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"test"},{"name":"p026_tlt07b","elements":[{"type":"html","name":"stim_tlt07b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Un videogioco online regala skin a chi gioca. Si provano due versioni. Versione 1: una skin ogni 10 partite. Versione 2: la skin arriva a caso, in media ogni 10 partite.</p></div>","visibleIf":"({forma_test} = ''B'')"},{"name":"tlt07b","title":"Con quale versione si giocano più partite?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Con la 1: i premi regolari creano più dipendenza"},{"value":2,"text":"Uguale: in media i premi sono gli stessi"},{"value":3,"text":"Con la 2: non sapere quando arriva fa riprovare"},{"value":4,"text":"Con la 1: sapere quando arriva il premio motiva"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"test"},{"name":"p027_tlt08b","elements":[{"type":"html","name":"stim_tlt08b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Marco gioca su un&#x27;app di casinò online. Perde 60 euro e chiude l&#x27;app. Dieci minuti dopo arriva una notifica: &#x27;Marco, la fortuna sta per girare! 20 giri gratis solo per te, fino a mezzanotte.&#x27;</p></div>","visibleIf":"({forma_test} = ''B'')"},{"name":"tlt08b","title":"Perché la notifica arriva proprio adesso? Scegli il motivo più probabile.","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"L''app vuole aiutarlo a rifarsi della perdita"},{"value":2,"text":"È un caso: le notifiche arrivano a tutti"},{"value":3,"text":"L''app vuole vendere i suoi dati ad altre aziende"},{"value":4,"text":"L''app vede che ha smesso e prova a richiamarlo"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"test"},{"name":"p028_tlt09b","elements":[{"type":"html","name":"stim_tlt09b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Un canale Telegram di pronostici pubblica ogni giorno le foto delle schedine vincenti dei suoi iscritti, con la scritta: &#x27;Altri 15 vincitori oggi! Entra nel gruppo VIP.&#x27;</p></div>","visibleIf":"({forma_test} = ''B'')"},{"name":"tlt09b","title":"Su chi legge, che effetto hanno più spesso quelle foto?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Informano: mostrano quanto spesso si vince"},{"value":2,"text":"Allontanano: si capisce che il canale è una truffa"},{"value":3,"text":"Nessuno: chi legge non si lascia influenzare"},{"value":4,"text":"Fanno sembrare facile vincere e spingono a provare"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"test"},{"name":"p029_tlt10b","elements":[{"type":"html","name":"stim_tlt10b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Un&#x27;autorità prepara nuove regole per i casinò online. Vuole aggiungerne una sola per proteggere chi gioca e ne sta valutando quattro.</p></div>","visibleIf":"({forma_test} = ''B'')"},{"name":"tlt10b","title":"Quale di queste regole protegge di più?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Un limite di perdita deciso prima e non alzabile"},{"value":2,"text":"Un bonus di consolazione dopo tre perdite di fila"},{"value":3,"text":"Un avviso: ''Il gioco può creare dipendenza''"},{"value":4,"text":"Un elenco delle ultime vincite, per trasparenza"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"test"},{"name":"p030_istr_grcs","elements":[{"type":"html","name":"istr_grcs","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Qui trovi alcune frasi sul gioco d&#x27;azzardo.</p><p style=\"margin:0 0 6px;line-height:1.6;\">Per ognuna indica quanto sei d&#x27;accordo.</p><p style=\"margin:0 0 6px;l' WHERE id = '634d0f93-ca2e-56a3-ab6e-ded17f13de95';
