xt":"Moderatamente d''accordo"},{"value":7,"text":"Del tutto d''accordo"}]}],"nx_block":"grcs"},{"name":"p038_grcs13","elements":[{"name":"grcs13","title":"Ho dei rituali e delle abitudini che aumentano le mie probabilità di vincere.","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Del tutto in disaccordo"},{"value":2,"text":"Moderatamente in disaccordo"},{"value":3,"text":"Leggermente in disaccordo"},{"value":4,"text":"Né d''accordo né in disaccordo"},{"value":5,"text":"Leggermente d''accordo"},{"value":6,"text":"Moderatamente d''accordo"},{"value":7,"text":"Del tutto d''accordo"}]}],"nx_block":"grcs"},{"name":"p039_grcs14","elements":[{"name":"grcs14","title":"Se ho vinto una volta, vincerò di sicuro ancora.","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Del tutto in disaccordo"},{"value":2,"text":"Moderatamente in disaccordo"},{"value":3,"text":"Leggermente in disaccordo"},{"value":4,"text":"Né d''accordo né in disaccordo"},{"value":5,"text":"Leggermente d''accordo"},{"value":6,"text":"Moderatamente d''accordo"},{"value":7,"text":"Del tutto d''accordo"}]}],"nx_block":"grcs"},{"name":"p040_grcs15","elements":[{"name":"grcs15","title":"Pensare che le mie perdite siano solo una questione di probabilità mi fa continuare a giocare.","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Del tutto in disaccordo"},{"value":2,"text":"Moderatamente in disaccordo"},{"value":3,"text":"Leggermente in disaccordo"},{"value":4,"text":"Né d''accordo né in disaccordo"},{"value":5,"text":"Leggermente d''accordo"},{"value":6,"text":"Moderatamente d''accordo"},{"value":7,"text":"Del tutto d''accordo"}]}],"nx_block":"grcs"},{"name":"p041_grcs18","elements":[{"name":"grcs18","title":"Conservo oggetti particolari che aumentano le mie probabilità di vincere.","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Del tutto in disaccordo"},{"value":2,"text":"Moderatamente in disaccordo"},{"value":3,"text":"Leggermente in disaccordo"},{"value":4,"text":"Né d''accordo né in disaccordo"},{"value":5,"text":"Leggermente d''accordo"},{"value":6,"text":"Moderatamente d''accordo"},{"value":7,"text":"Del tutto d''accordo"}]}],"nx_block":"grcs"},{"name":"p042_grcs19","elements":[{"name":"grcs19","title":"Riesco in parte a prevedere quando vincerò.","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Del tutto in disaccordo"},{"value":2,"text":"Moderatamente in disaccordo"},{"value":3,"text":"Leggermente in disaccordo"},{"value":4,"text":"Né d''accordo né in disaccordo"},{"value":5,"text":"Leggermente d''accordo"},{"value":6,"text":"Moderatamente d''accordo"},{"value":7,"text":"Del tutto d''accordo"}]}],"nx_block":"grcs"},{"name":"p043_grcs20","elements":[{"name":"grcs20","title":"Ricordare quanto ho vinto l''ultima volta mi fa continuare a giocare.","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Del tutto in disaccordo"},{"value":2,"text":"Moderatamente in disaccordo"},{"value":3,"text":"Leggermente in disaccordo"},{"value":4,"text":"Né d''accordo né in disaccordo"},{"value":5,"text":"Leggermente d''accordo"},{"value":6,"text":"Moderatamente d''accordo"},{"value":7,"text":"Del tutto d''accordo"}]}],"nx_block":"grcs"},{"name":"p044_grcs23","elements":[{"name":"grcs23","title":"Se cambio sempre i numeri che gioco, ho meno probabilità di vincere che se gioco sempre gli stessi.","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Del tutto in disaccordo"},{"value":2,"text":"Moderatamente in disaccordo"},{"value":3,"text":"Leggermente in disaccordo"},{"value":4,"text":"Né d''accordo né in disaccordo"},{"value":5,"text":"Leggermente d''accordo"},{"value":6,"text":"Moderatamente d''accordo"},{"value":7,"text":"Del tutto d''accordo"}]}],"nx_block":"grcs"},{"name":"p045_intro_cmp","elements":[{"type":"html","name":"intro_cmp","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Ora alcune domande sui giochi in cui si puntano soldi veri.</p><p style=\"margin:0 0 6px;line-height:1.6;\"><strong style=\"color:#286181\">Le risposte sono riservate: nessuno, né a scuola né a casa, saprà che cosa hai risposto tu.</strong></p><p style=\"margin:0 0 6px;line-height:1.6;\"><strong style=\"color:#286181\">Non ci sono risposte giuste o sbagliate.</strong></p></div>"}],"nx_block":"comportamento","title":"Giochi con soldi veri","nx_section_title":"Giochi con soldi veri","nx_section_id":"comportamento","description":"Circa 2 minuti"},{"name":"p046_cmp_3m","elements":[{"name":"cmp_3m","title":"Dal [DATA_3M] a oggi, hai giocato soldi veri a questi giochi, almeno una volta?","type":"matrix","description":"Rispondi Sì o No per ogni riga. Conta anche quando i soldi erano di altri. Non contare i giochi con monete finte.","columns":[{"value":1,"text":"Sì"},{"value":0,"text":"No"}],"rows":[{"value":"cmp01","text":"Gratta e Vinci o altri biglietti da grattare (anche online)"},{"value":"cmp02","text":"Lotto, SuperEnalotto, Lotteria Italia, altre lotterie o bingo (anche online)"},{"value":"cmp03","text":"Scommesse sportive, anche su cavalli o partite virtuali, in agenzia, bar o tabaccheria"},{"value":"cmp04","text":"Scommesse sportive, anche su cavalli o partite virtuali, su siti o app"},{"value":"cmp05","text":"Slot machine o videolottery (VLT) in bar, tabaccheria o sala giochi"},{"value":"cmp07","text":"Slot, roulette, poker o altri giochi da casinò su siti o app"},{"value":"cmp08","text":"Carte o dadi fuori dalla famiglia (per esempio con amici e amiche)"},{"value":"cmp10","text":"Scommesse tra amici e amiche (per esempio su una partita o una sfida)"},{"value":"cmp11","text":"Scommesse o roulette con skin dei videogiochi, su siti fuori dal gioco"}]}],"nx_block":"comportamento"},{"name":"p047_cmp12","elements":[{"type":"html","name":"stim_cmp12","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Alcuni videogiochi hanno casse premio (loot box): casse, pacchetti o <strong style=\"color:#286181\">premi a sorpresa che danno un oggetto a caso</strong>, come una skin, un personaggio o un calciatore.</p><p style=\"margin:0 0 6px;line-height:1.6;\">Alcune si pagano con soldi veri.</p></div>"},{"name":"cmp12","title":"Dal [DATA_3M] a oggi, hai giocato a videogiochi che hanno casse premio?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Sì"},{"value":2,"text":"No"},{"value":3,"text":"Non lo so"}]}],"nx_block":"comportamento"},{"name":"p048_cmp13","elements":[{"type":"html","name":"stim_cmp13","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Conta anche le casse pagate con monete o gemme comprate con soldi veri, anche con una carta regalo.</p><p style=\"margin:0 0 6px;line-height:1.6;\"><strong style=\"color:#286181\">Non contare quelle avute gratis.</strong></p></div>"},{"name":"cmp13","title":"Dal [DATA_3M] a oggi, in quanti giorni hai comprato casse premio con soldi veri?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Nessun giorno"},{"value":2,"text":"1-2 giorni"},{"value":3,"text":"3-5 giorni"},{"value":4,"text":"6-12 giorni"},{"value":5,"text":"Più di 12 giorni (circa ogni settimana o più)"}]}],"nx_block":"comportamento"},{"name":"p049_cmp14","elements":[{"type":"html","name":"stim_cmp14","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Conta anche le monete o gemme usate per le casse.</p><p style=\"margin:0 0 6px;line-height:1.6;\"><strong style=\"color:#286181\">Se non ricordi bene, scegli la risposta più vicina.</strong></p></div>"},{"name":"cmp14","title":"Dal [DATA_3M] a oggi, quanti soldi veri hai speso in tutto per le casse premio?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Niente"},{"value":2,"text":"Fino a 10 euro"},{"value":3,"text":"Da 11 a 30 euro"},{"value":4,"text":"Da 31 a 100 euro"},{"value":5,"text":"Da 101 a 300 euro"},{"value":6,"text":"Più di 300 euro"}]}],"nx_block":"comportamento"},{"name":"p050_qd12","elements":[{"type":"html","name":"stim_qd12","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Ultima domanda. <strong style=\"color:#286181\">Rispondi con sincerità: la tua risposta non cambia niente per te.</strong></p></div>"},{"name":"qd12","title":"Quanto impegno hai messo nel rispondere a questo questionario?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Nessuno"},{"value":2,"text":"Poco"},{"value":3,"text":"Abbastanza"},{"value":4,"text":"Molto"},{"value":5,"text":"Il massimo"}]},{"type":"html","name":"qd13","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Hai finito. Grazie!</p></div><div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Se qualche domanda ti ha fatto pensare a un problema con il gioco d&#x27;azzardo, tuo o di una persona a cui tieni, per esempio qualcuno della tua famiglia, <strong style=\"color:#286181\">puoi chiedere aiuto.</strong></p></div><ul style=\"list-style:disc outside;margin:0 0 14px;padding-left:1.3em;line-height:1.6;\"><li style=\"display:list-item;margin:0 0 8px\">Telefono Verde Nazionale per le problematiche legate al gioco d&#x27;azzardo, dell&#x27;Istituto Superiore di Sanità: <strong style=\"color:#286181\">800 55 88 22</strong>. È gratuito e anonimo. Risponde dal lunedì al venerdì, dalle 10 alle 16, tranne i festivi. Puoi chiamare anche per un familiare.</li><li style=\"display:list-item;margin:0 0 8px\">Un adulto di cui ti fidi: un genitore, un insegnante.</li></ul><div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Altre informazioni sul sito usciredalgioco.iss.it.</p></div>"}],"title":"Ultima pagina"}]}' WHERE id = '634d0f93-ca2e-56a3-ab6e-ded17f13de95';
